def test_surf_pause_uses_local_sleep_without_surf_wait(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    calls: list[tuple[str, object]] = []

    def fail_surf(*_: object, **__: object) -> str:
        raise AssertionError("surf wait should not be called for pacing sleeps")

    def record_sleep(seconds: object) -> None:
        calls.append(("sleep", seconds))

    monkeypatch.setattr(browser_capture, "_surf", fail_surf)
    monkeypatch.setattr(browser_capture.time, "sleep", record_sleep)
    browser_capture.reset_browser_control_events()

    browser_capture._surf_pause(Path("surf/run.sh"), "1", timeout=15)

    assert calls == [("sleep", 1.0)]
    summary = browser_capture.browser_control_summary()
    assert summary["status"] == "OK"
    assert summary["counts"] == {}


def test_close_tab_records_browser_control_failure(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    sleeps: list[float] = []
    close_calls: list[tuple[object, ...]] = []

    def close_timeout(*args: object, **__: object) -> str:
        close_calls.append(args)
        raise subprocess.TimeoutExpired(["surf", "tab.close", "123"], 30)

    monkeypatch.setattr(browser_capture, "_surf", close_timeout)
    monkeypatch.setattr(browser_capture.time, "sleep", lambda seconds: sleeps.append(seconds))
    browser_capture.reset_browser_control_events()

    browser_capture._close_tab(Path("surf/run.sh"), "123", "test")

    summary = browser_capture.browser_control_summary()
    assert summary["status"] == "DEGRADED"
    assert summary["counts"] == {"tab_close_failed": 1}
    assert summary["recent"][0]["tab_id"] == "123"
    assert summary["recent"][0]["timeout"] == 58
    assert summary["recent"][0]["details"]["attempted_modes"] == [
        "locked",
        "no_lock_cleanup",
        "final_batch_sweep",
        "final_individual_sweep",
    ]
    assert close_calls[0][1:] == ("tab.close", "123", "--lock-timeout", "5")
    assert close_calls[1][1:] == ("tab.close", "123", "--no-lock")
    assert close_calls[2][1:] == ("tab.list", "--json")
    assert close_calls[3][1:] == ("tab.close", "--ids", "123", "--no-lock")
    assert sleeps == []


