def test_isolated_meetup_capture_terminates_wedged_child(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    def wedged_capture(*_: object, **__: object) -> dict[str, object]:
        time.sleep(10)
        return {"status": "OK"}

    monkeypatch.setattr(browser_capture, "capture_meetup_buffalo", wedged_capture)

    started = time.monotonic()
    receipt = capture_meetup_buffalo_isolated(tmp_path, timeout_seconds=1)

    assert time.monotonic() - started < 5
    assert receipt["status"] == "FAILED"
    assert "isolated timeout 1s" in receipt["error"]
    assert receipt["blocked_by_systemic_failure"] is True
    assert receipt["failure_signature"] == "meetup_isolated_capture_timeout"
    assert receipt["group_capture_skipped"] == 12
    stored = json.loads((tmp_path / "meetup-capture-receipt.json").read_text(encoding="utf-8"))
    assert stored["status"] == "FAILED"
    assert stored["blocked_by_systemic_failure"] is True


def test_meetup_group_capture_circuit_breaks_repeated_timeouts(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(browser_capture, "ensure_browser", lambda _surf_run: "existing")
    monkeypatch.setenv("MONITOR_MEETUP_MAX_GROUP_FAILURES", "3")
    group_urls = [
        f"https://www.meetup.com/group-{idx}/"
        for idx in range(5)
    ]

    def fake_surf(_surf_run: Path, *args: str, timeout: int = 90) -> str:
        del _surf_run, timeout
        if args[0] == "tab.new":
            return "123: tab"
        if args[0] == "wait":
            return ""
        if args[0] == "tab.close":
            return ""
        if args[0] == "tab.list":
            return '[{"id":123,"title":"Meetup","url":"https://www.meetup.com/find/"}]'
        if args[0] == "snap":
            output = Path(args[args.index("--output") + 1])
            output.write_bytes(b"png")
            return str(output)
        if args[0] == "js":
            script = args[1]
            if "find/?source=GROUPS" not in script:
                raise subprocess.TimeoutExpired(args, 20)
            return "NAV"
        raise AssertionError(f"unexpected surf args: {args!r}")

    def fake_snapshot(_surf_run: Path, _tab_id: str) -> dict[str, object]:
        return {
            "title": "Search groups",
            "text": "Buffalo groups",
            "links": group_urls,
        }

    monkeypatch.setattr(browser_capture, "_surf", fake_surf)
    monkeypatch.setattr(browser_capture, "_surf_pause", lambda *args, **kwargs: None)
    monkeypatch.setattr(browser_capture, "_meetup_page_snapshot", fake_snapshot)

    receipt = capture_meetup_buffalo(tmp_path, max_group_pages=5)

    assert receipt["group_capture_failed"] == 3
    assert receipt["group_capture_skipped"] == 2
    assert receipt["blocked_by_systemic_failure"] is True
    assert receipt["failure_signature"] == "meetup_group_detail_capture_failed"
    evidence = json.loads((tmp_path / "meetup-buffalo-evidence.json").read_text(encoding="utf-8"))
    assert evidence["blocked_by_systemic_failure"] is True
    assert len(evidence["group_capture_failures"]) == 3
    assert len(evidence["skipped_group_urls"]) == 2
    assert evidence["site_recovery_status"] == "DIAGNOSTIC_BUNDLE_WRITTEN"
    diagnostic = receipt["diagnostic_bundle"]
    assert diagnostic["reason"] == "meetup_group_detail_capture_failed"
    manifest = json.loads(Path(diagnostic["manifest"]).read_text(encoding="utf-8"))
    assert manifest["schema"] == "monitor_opportunities.surf_diagnostic_bundle.v1"
    assert manifest["source"] == "meetup_buffalo"
    assert manifest["tab_id"] == "123"
    assert manifest["external_effects"] is False
    assert "tab_list" in manifest["artifacts"]
    assert "screenshot" in manifest["artifacts"]


def test_meetup_capture_uses_bounded_waits_and_eight_group_budget(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(browser_capture, "ensure_browser", lambda _surf_run: "existing")
    technology_urls = [f"https://www.meetup.com/tech-group-{idx}/" for idx in range(6)]
    business_urls = [f"https://www.meetup.com/business-group-{idx}/" for idx in range(6)]
    waits: list[str] = []
    current_page = "546"

    def fake_surf(_surf_run: Path, *args: str, timeout: int = 90) -> str:
        nonlocal current_page
        del _surf_run, timeout
        if args[0] == "tab.new":
            current_page = "546"
            return "123: tab"
        if args[0] == "tab.close":
            return ""
        if args[0] == "js":
            script = args[1]
            if "categoryId=405" in script:
                current_page = "405"
            elif "categoryId=546" in script:
                current_page = "546"
            elif "business-group" in script:
                current_page = "business-group"
            elif "tech-group" in script:
                current_page = "tech-group"
            return "NAV"
        raise AssertionError(f"unexpected surf args: {args!r}")

    def fake_snapshot(_surf_run: Path, _tab_id: str) -> dict[str, object]:
        links = business_urls if current_page == "405" else technology_urls
        return {
            "title": "Buffalo Meetup Groups",
            "text": "Buffalo technology and business groups",
            "links": links,
        }

    def fake_pause(_surf_run: Path, seconds: str, timeout: int = 30) -> None:
        del _surf_run, timeout
        waits.append(seconds)

    monkeypatch.setattr(browser_capture, "_surf", fake_surf)
    monkeypatch.setattr(browser_capture, "_surf_pause", fake_pause)
    monkeypatch.setattr(browser_capture, "_meetup_page_snapshot", fake_snapshot)

    receipt = capture_meetup_buffalo(tmp_path, max_group_pages=8)

    assert receipt["status"] == "OK"
    assert receipt["groups_captured"] == 8
    assert receipt["max_group_pages"] == 8
    assert receipt["category_wait_seconds"] == "4"
    assert receipt["group_wait_seconds"] == "3"
    assert waits.count("4") == 2
    assert waits.count("3") == 8
    evidence = json.loads((tmp_path / "meetup-buffalo-evidence.json").read_text(encoding="utf-8"))
    assert len(evidence["groups"]) == 8
    assert {"405", "546"}.issubset({group["category_id"] for group in evidence["groups"]})
    assert evidence["external_effects"] is False
